const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const read=f=>fs.readFileSync(path.join(__dirname,f.startsWith('../')?f:path.join('world',f)),'utf8');
let world=read('../woodland.js').replace(/^import \* as T from '[^']+';\s*/,'');
world=world.replace('const planet=new T.Group();scene.add(planet);',`const planet=new T.Group();scene.add(planet);
const assetRoots=[];const originalPlanetAdd=planet.add;planet.add=function(...objects){for(const object of objects){if(!object.userData.assetSourceRoot){object.userData.assetSourceRoot='root_'+String(assetRoots.length).padStart(4,'0');assetRoots.push(object);}}return originalPlanetAdd.apply(this,objects);};window.HerstoryAssetRoots=assetRoots;`);
// Spread the original farm and forest landmarks, keeping each model attached to the ground.
world=world.replace("new T.Vector3(-.48,-.42,.94)","new T.Vector3(-.66,-.65,.86)");
world=world.replace("function at(key,x,y,day=1){return anchor(offset(biomes[key].dir,x,y),day);}","function at(key,x,y,day=1){const spread=key==='farm'?1.28:key==='forest'?1.18:1;const g=anchor(offset(biomes[key].dir,x*spread,y*spread),day);g.userData.zone=key;return g;}");
world=world.replace("const pondDir=new T.Vector3(-.05,.02,1)","const pondDir=new T.Vector3(.26,-.12,1)");
world=world.replace("g=anchor(offset(pondDir,x*1.12,z*1.12),1);if", "g=anchor(offset(pondDir,x*1.12,z*1.12),1);g.userData.pondEdge=true;if");
world=world.replaceAll("'#edf1dc'","'#f5f5e9'");
world=world.replace(/\/\/ Timber learning village[\s\S]*?(?=\/\/ Elevated coastal railway)/, '');
world=world.replace(/\/\/ Elevated coastal railway[\s\S]*?(?=\/\/ Ceramic, hardware)/,'const carriages=[];\n');
world=world.replace('function pine(g,h=1){','function originalPine(g,h=1){').replace('function tree(g,h=1){','function originalTree(g,h=1){');
world='function pine(g,h=1){const p=new T.Group();p.userData.planetTree=true;g.add(p);originalPine(p,h);}\nfunction tree(g,h=1){const p=new T.Group();p.userData.planetTree=true;g.add(p);originalTree(p,h);}\n'+world;
const city=read('manhattan-world.js').replace('function cityTree(g,s=1){','function cityTree(g,s=1){g.userData.planetTree=true;');
world=world.replace('let auto=false,goal=null,day=14;',city+'\n'+read('integrated-planet.js')+'\n'+read('peach-castle.js')+'\n'+read('asset-expansion.js')+'\n'+read('french-lake.js')+'\n'+read('open-lake.js')+'\n'+read('layout-clearance.js')+'\n'+read('starlight-swallows.js')+'\nlet auto=false,goal=null,day=14;');
world=world.replace('animatePond(reduced?0:t);renderer.render(scene,camera);','animatePond(reduced?0:t);animateCity(reduced?0:t,dt);animateIntegrated(t);animateAssets(t,dt);animateFrenchLake(t);starlightSwallows.animate(reduced?0:t);if(cityExplorer.active)renderer.render(streetScene,streetCamera);else renderer.render(scene,camera);');
world=world.replace("e=>{renderer.domElement.setPointerCapture", "e=>{if(cityExplorer.active)return;renderer.domElement.setPointerCapture");
world=world.replace("e=>{if(!pointers.has", "e=>{if(cityExplorer.active)return;if(!pointers.has");
world=world.replace('e.preventDefault();distance=', 'e.preventDefault();if(cityExplorer.active){window.manhattanExplorer.zoom(e.deltaY*.008);return;}distance=');
const begin=world.indexOf('function resize(){'),end=world.indexOf("addEventListener('resize',resize);",begin);
if(begin<0||end<0)throw Error('Resize function not found');
world=world.slice(0,begin)+`function resize(){const w=host.clientWidth,h=host.clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h);planet.scale.setScalar(Math.min(w,h)/h*1.04);planet.position.set(0,.08,0);orbit.visible=false;}\n`+world.slice(end);
world=world.replace("window.planetDemo={renderer,scene,planet,biomes,growthObjects,setRegion,coverage};",`window.planetDemo={renderer,scene,planet,biomes,growthObjects,setRegion,coverage};
window.herstoryWorld={setStage(value){day=value;growthObjects.forEach(g=>g.visible=g.userData.day<=day);},focus(key){window.manhattanExplorer.exit();setRegion(key);distance=key==='all'?11.6:10.6;},snapshot(){return window.manhattanExplorer.snapshot();}};
document.querySelector('#reset').onclick=()=>window.herstoryWorld.focus('all');
new ResizeObserver(resize).observe(host);`);
const lib=read('../vendor/three.module.js'),ex=lib.match(/export\s*\{([^}]+)\};?\s*$/);if(!ex)throw Error('Library exports missing');
const props=ex[1].split(',').map(s=>{const p=s.trim().split(/\s+as\s+/);return p.length===2?`${p[1]}:${p[0]}`:p[0]}).join(',');
const code=`(()=>{const T=(()=>{${lib.slice(0,ex.index)};return {${props}};})();\n${world}\n})();`;new vm.Script(code);
const output=path.join(__dirname,'world','planet-world.js');fs.writeFileSync(output,code);console.log(JSON.stringify({output,bytes:Buffer.byteLength(code),syntax:'passed'}));
